package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static io.github.campione01.mineclientbridge.ScopedEntityPolicy.*;
/** Offline reserialization of retained admission, never a replay or claim about the unretained current guard. */
public final class RetainedAdmissionStopChecks {
 static final Gson WIRE=new GsonBuilder().serializeNulls().disableHtmlEscaping().create();
 static JsonObject findGuard(JsonElement e){if(e.isJsonObject()){JsonObject j=e.getAsJsonObject();if(j.has("policy")&&j.get("policy").isJsonPrimitive()&&j.get("policy").getAsString().equals(ScopedRouteThreatPolicy.POLICY)&&j.has("rows"))return j;for(var v:j.entrySet()){JsonObject r=findGuard(v.getValue());if(r!=null)return r;}}else if(e.isJsonArray())for(var v:e.getAsJsonArray()){JsonObject r=findGuard(v);if(r!=null)return r;}return null;}
 static V v(JsonArray a){return new V(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
 static Box box(JsonArray a){return new Box(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),a.get(3).getAsDouble(),a.get(4).getAsDouble(),a.get(5).getAsDouble());}
 static ScopedRouteThreatPolicy.Frame frame(JsonObject g){var rows=new ArrayList<ScopedRouteThreatPolicy.Row>();JsonObject nativeFact=null;for(var e:g.getAsJsonArray("rows")){var r=e.getAsJsonObject();boolean removed=r.get("removed").getAsBoolean();Flags flags=null;if(!removed){var f=r.getAsJsonObject("flags");flags=new Flags(f.get("living").getAsBoolean(),f.get("alive").getAsBoolean(),f.get("dying").getAsBoolean(),f.get("passenger").getAsBoolean(),f.get("has_passengers").getAsBoolean(),f.get("leashed").getAsBoolean(),f.get("no_physics").getAsBoolean(),f.get("on_fire").getAsBoolean(),f.get("active_effect_count").getAsInt(),f.get("hurt_time").getAsInt(),f.get("mob_target_uuid").isJsonNull()?null:f.get("mob_target_uuid").getAsString());}JsonObject n=r.has("native_living")?r.getAsJsonObject("native_living"):null;if(n!=null)nativeFact=n;rows.add(new ScopedRouteThreatPolicy.Row(r.get("id").getAsInt(),r.get("uuid").getAsString(),r.get("type").getAsString(),r.get("class").getAsString(),removed,removed?null:v(r.getAsJsonArray("position")),removed?null:box(r.getAsJsonArray("aabb")),removed?null:v(r.getAsJsonArray("velocity")),removed?null:v(r.getAsJsonArray("lerp_target")),flags,removed?null:box(r.getAsJsonArray("projected_aabb")),n));}if(nativeFact==null)throw new AssertionError("Missing retained native facts");return new ScopedRouteThreatPolicy.Frame(g.get("source_tick").getAsLong(),Long.parseLong(g.get("source_nano").getAsString()),g.get("remaining_projection_ticks").getAsInt(),g.get("self_count").getAsInt(),box(g.getAsJsonArray("prism")),box(g.getAsJsonArray("swept_aabb")),v(g.getAsJsonArray("player_position")),nativeFact.get("player_uuid").getAsString(),nativeFact.get("world_generation").getAsString(),nativeFact.get("dimension").getAsString(),g.get("selected_target_uuid").getAsString(),rows,true);}
 static int bytes(JsonObject j){return WIRE.toJson(j).getBytes(StandardCharsets.UTF_8).length;}
 static void write(Path p,JsonObject j)throws Exception{Files.writeString(p,WIRE.toJson(j),StandardOpenOption.CREATE_NEW);}
 public static void main(String[] args)throws Exception{Path receipt=Path.of(args[0]),out=Path.of(args[1]);JsonObject retained=findGuard(JsonParser.parseString(Files.readString(receipt)));if(retained==null)throw new AssertionError("Retained admission missing");var frame=frame(retained);JsonObject rebuilt=frame.json();if(!retained.equals(rebuilt))throw new AssertionError("Rebuilt admission changes retained facts");write(out.resolve("retained-admission-gson.json"),retained);write(out.resolve("rebuilt-admission-gson.json"),rebuilt);JsonObject result=new JsonObject();result.addProperty("retained_admission_gson_utf8_bytes",bytes(retained));result.addProperty("rebuilt_frame_json_gson_utf8_bytes",bytes(rebuilt));result.addProperty("rows",frame.rows().size());result.addProperty("population",frame.population());result.addProperty("frame_semantically_equal",true);result.addProperty("scope","Retained admission reconstructed through actual Frame constructor/json/stop; current historical stop frame and exception were not retained. This does not prove the historical exception.");try{JsonObject stop=frame.stop(true);write(out.resolve("rebuilt-stop-gson.json"),stop);result.addProperty("stop_outcome","accepted");result.addProperty("stop_proof_gson_utf8_bytes",bytes(stop));}catch(RuntimeException failure){result.addProperty("stop_outcome","rejected");result.addProperty("exception_class",failure.getClass().getName());result.addProperty("exception_reason",failure.getMessage());}write(out.resolve("reproduction.json"),result);System.out.println(WIRE.toJson(result));}
}
